steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      query {
        teams(name: \"Web\") {
          nodes {
            id
            name
            issues(filter: { title: { contains: \"Design system audit\" } }) {
              nodes {
                id
                title
                priority
                priorityName
                subscribeUsers {
                  nodes {
                    id
                    name
                  }
                }
              }
            }
          }
        }
      }
    "
  }'
